"""File capture: files the printer announces are downloaded once, stored by content, sorted and kept."""

import base64
import time

import pytest
from fastapi.testclient import TestClient

import app.library as library_mod
from app.config import Settings
from app.gcode_meta import parse
from app.library import wanted
from app.main import create_app

from .conftest import wait_for_sync

PNG = base64.b64encode(b"\x89PNG\r\n\x1a\n" + b"\x00" * 40).decode()


def sliced(name: str, extra: str = "") -> bytes:
    return (
        "; generated by Creality Print 6.1\n"
        "; thumbnail begin 300x300 60\n"
        f"; {PNG}\n"
        "; thumbnail end\n"
        "; estimated printing time (normal mode) = 1h 12m 56s\n"
        "; filament_type = PETG-CF\n"
        "; filament_colour = #222222\n"
        "; total filament used [g] = 23.45\n"
        "; total layers count = 240\n"
        "; layer_height = 0.2\n"
        f"; printer_model = Creality K1C\n; part = {name}\n{extra}"
        "G28\nG1 X10 Y10 Z0.2 E1 F1200\nG1 X20 Y10 E2\n"
    ).encode()


@pytest.fixture
def client(tmp_path, printers_file, monkeypatch):
    monkeypatch.setattr(library_mod, "QUIET_SECONDS", 0.4)
    monkeypatch.setattr(library_mod, "FALLBACK_SECONDS", 1.0)
    s = Settings(data_dir=tmp_path / "data", printers_file=printers_file, reconnect_seconds=0.3,
                 static_dir=tmp_path / "none", library_root=tmp_path / "library")
    with TestClient(create_app(s)) as c:
        wait_for_sync(lambda: c.get("/api/printers/k1c").json()["state"] == "printing")
        yield c


def files(c, **q):
    return c.get("/api/files", params=q).json()


def test_wanted_paths():
    assert wanted({"root": "gcodes", "path": "rail_A.gcode"}) == "rail_A.gcode"
    assert wanted({"root": "gcodes", "path": "sub/part.3mf"}) == "sub/part.3mf"
    assert wanted({"root": "gcodes", "path": ".thumbs/rail_A-300x300.png"}) is None
    assert wanted({"root": "gcodes", "path": "notes.txt"}) is None
    assert wanted({"root": "config", "path": "printer.cfg"}) is None
    assert wanted({"root": "gcodes", "path": "../x.gcode"}) is None


def test_header_is_read(tmp_path):
    p = tmp_path / "a.gcode"
    p.write_bytes(sliced("a"))
    meta, thumb = parse(p)
    assert meta["estimated_seconds"] == 4376 and meta["filament_type"] == ["PETG-CF"]
    assert meta["filament_g"] == 23.45 and meta["layers"] == 240 and meta["printer_model"] == "Creality K1C"
    assert thumb and thumb.startswith(b"\x89PNG")


def fetched(fake_server, name: str) -> int:
    return sum(1 for p in fake_server.fake.http_requests if p.endswith("/gcodes/" + name))


def test_upload_is_captured_once_after_it_settles(client, fake_server):
    fake_server.run(fake_server.fake.upload("rail_B.gcode", sliced("B")))
    wait_for_sync(lambda: any(f["filename"] == "rail_B.gcode" for f in files(client, inbox="true")))
    f = next(f for f in files(client, inbox="true") if f["filename"] == "rail_B.gcode")
    assert f["filename"] == "rail_B.gcode" and f["label"] is None and f["thumbnail"]
    assert f["meta"]["filament_type"] == ["PETG-CF"] and f["size"] == len(sliced("B"))
    # One download of the finished file; nothing for the thumbnails or the half-sent file.
    assert fetched(fake_server, "rail_B.gcode") == 1
    assert not [p for p in fake_server.fake.http_requests if ".thumbs" in p]
    assert client.get(f"/api/files/{f['id']}/raw").content == sliced("B")
    assert client.get(f"/api/files/{f['id']}/thumbnail").headers["content-type"] == "image/png"


def test_same_content_is_one_entry_and_keeps_its_label(client, fake_server):
    fake_server.run(fake_server.fake.upload("rail_B.gcode", sliced("B")))
    wait_for_sync(lambda: len(files(client)) >= 1 and any(f["filename"] == "rail_B.gcode" for f in files(client)))
    fid = next(f["id"] for f in files(client) if f["filename"] == "rail_B.gcode")
    assert client.patch(f"/api/files/{fid}", json={"label": "Drive mount"}).json()["label"] == "Drive mount"
    fake_server.run(fake_server.fake.upload("rail_B_v2.gcode", sliced("B")))  # same bytes, new name
    wait_for_sync(lambda: client.get(f"/api/files/{fid}").json()["filename"] == "rail_B_v2.gcode")
    assert [f["id"] for f in files(client, label="Drive mount")] == [fid]
    assert files(client, inbox="true") == [] or all(f["id"] != fid for f in files(client, inbox="true"))
    labels = client.get("/api/labels").json()
    assert {"name": "Drive mount", "files": 1} in labels


def test_deleted_on_printer_stays_deleted_in_app_goes(client, fake_server, tmp_path):
    fake_server.run(fake_server.fake.upload("rail_C.gcode", sliced("C")))
    wait_for_sync(lambda: any(f["filename"] == "rail_C.gcode" for f in files(client)))
    fid = next(f["id"] for f in files(client) if f["filename"] == "rail_C.gcode")
    fake_server.run(fake_server.fake.delete("rail_C.gcode"))
    assert client.get(f"/api/files/{fid}").status_code == 200  # still ours
    assert client.delete(f"/api/files/{fid}").json() == {"ok": True}
    assert client.get(f"/api/files/{fid}").status_code == 404
    assert not list((tmp_path / "library" / "files").glob("*")) or all(
        "rail_C" not in p.name for p in (tmp_path / "library" / "files").iterdir())


def test_quick_resend_restarts_the_wait(client, fake_server):
    fake_server.run(fake_server.fake.upload("rail_D.gcode", sliced("D1"), gap=0.15))
    fake_server.run(fake_server.fake.upload("rail_D.gcode", sliced("D2"), gap=0.15))
    wait_for_sync(lambda: any(f["filename"] == "rail_D.gcode" for f in files(client)))
    assert fetched(fake_server, "rail_D.gcode") == 1
    f = next(f for f in files(client) if f["filename"] == "rail_D.gcode")
    assert client.get(f"/api/files/{f['id']}/raw").content == sliced("D2")


def test_history_records_prints_and_links_the_file(client, fake_server):
    # The print already running is recorded, and its file is kept through the once-per-print backstop.
    wait_for_sync(lambda: len(client.get("/api/history").json()) == 1)
    job = client.get("/api/history").json()[0]
    assert job["filename"] == "phone_stand_v3.gcode" and job["result"] == "printing"
    wait_for_sync(lambda: client.get("/api/history").json()[0]["file_id"] is not None)
    downloads = fake_server.fake.gcode_downloads
    fake_server.scenario("complete")
    wait_for_sync(lambda: client.get("/api/history").json()[0]["result"] == "complete")
    fid = client.get("/api/history").json()[0]["file_id"]
    # A second print of the same file: a new job, and the stored copy is used, no download.
    fake_server.fake.start_progress = 0.01
    fake_server.scenario("printing")
    wait_for_sync(lambda: len(client.get("/api/history").json()) == 2)
    wait_for_sync(lambda: client.get("/api/printers/k1c/gcode/info").json()["state"] == "ready")
    assert fake_server.fake.gcode_downloads == downloads
    d = client.get(f"/api/files/{fid}").json()
    assert d["prints"] == 2 and d["source"] == "print"


def test_capture_off(tmp_path, printers_file, fake_server):
    s = Settings(data_dir=tmp_path / "data", printers_file=printers_file, reconnect_seconds=0.3,
                 static_dir=tmp_path / "none", capture_files=False)
    with TestClient(create_app(s)) as c:
        assert c.get("/api/files").status_code == 404
        assert c.get("/api/config").json()["capture_files"] is False


def test_unusable_library_folder_turns_capture_off(tmp_path, printers_file, fake_server):
    blocker = tmp_path / "library"
    blocker.write_text("not a folder")  # stands in for a folder the app can't write to
    s = Settings(data_dir=tmp_path / "data", printers_file=printers_file, reconnect_seconds=0.3,
                 static_dir=tmp_path / "none", library_root=blocker)
    with TestClient(create_app(s)) as c:
        wait_for_sync(lambda: c.get("/api/printers/k1c").json()["state"] == "printing")
        assert c.get("/api/config").json()["capture_files"] is False
        assert c.get("/api/files").status_code == 404


def test_silence_mid_upload_waits_for_the_finished_notice(client, fake_server):
    # What the K1C did on 2026-11-17: create_file, thumbnails, then 20+ s of nothing while
    # still writing, then modify_file. Nothing may be fetched before modify_file.
    big = sliced("Q") + b"G1 X1 Y1 E1\n" * 30000
    fake_server.run(fake_server.fake.upload("quant_1.gcode", big, gap=0.05, silence=0.8))  # longer than QUIET, shorter than FALLBACK
    wait_for_sync(lambda: any(f["filename"] == "quant_1.gcode" for f in files(client)))
    f = next(f for f in files(client) if f["filename"] == "quant_1.gcode")
    assert f["size"] == len(big) and fetched(fake_server, "quant_1.gcode") == 1
    assert client.get(f"/api/files/{f['id']}/raw").content == big


def test_finished_file_announced_once_is_kept_after_the_fallback(client, fake_server):
    # A plain Moonraker upload: one create_file with the full size, no modify_file.
    body = sliced("M")
    fake_server.fake.files["plain.gcode"] = body
    fake_server.run(fake_server.fake.notify("notify_filelist_changed", [
        {"action": "create_file", "item": {"root": "gcodes", "path": "plain.gcode", "size": len(body)}}]))
    wait_for_sync(lambda: any(f["filename"] == "plain.gcode" for f in files(client)), timeout=5)
    assert fetched(fake_server, "plain.gcode") == 1


def test_a_copy_of_the_wrong_size_is_not_kept(client, fake_server):
    # create_file says ~100 KB, modify_file never comes, and the printer still has half a file.
    body = sliced("P") + b"G1 X1 Y1 E1\n" * 30000
    fake_server.fake.files["partial.gcode"] = body[: len(body) // 2]
    fake_server.run(fake_server.fake.notify("notify_filelist_changed", [
        {"action": "create_file", "item": {"root": "gcodes", "path": "partial.gcode", "size": 102300}}]))
    wait_for_sync(lambda: fetched(fake_server, "partial.gcode") == 1, timeout=5)
    time.sleep(0.5)
    assert not any(f["filename"] == "partial.gcode" for f in files(client))
